window.VO = [{"id":"n01","text":"You're his only alibi.","at":0.24,"t0":0.12,"t1":1.39},{"id":"f00","text":"Tell them I was with you!","at":3.18,"t0":1.59,"t1":3.08},{"id":"n02","text":"Your best friend's locked up for robbing a watch shop.","at":6.66,"t0":3.33,"t1":6.14},{"id":"n03","text":"All the police have is a blurry photo of the robber.","at":12.78,"t0":6.39,"t1":9.155},{"id":"n03a","text":"All he has is you.","at":18.81,"t0":9.405,"t1":10.515},{"id":"o01","text":"Last Tuesday, seven forty. Where were you?","at":21.63,"t0":10.815,"t1":13.735},{"id":"n03b","text":"But do you really remember? Because for you, it was just another Tuesday.","at":30.07,"t0":15.035,"t1":18.92},{"id":"f01","text":"Please, think! We were at the chai stall, in the rain! You had ginger chai! You paid twenty rupees!","at":39.54,"t0":19.77,"t1":25.55},{"id":"f01r","text":"Don't you remember?","at":51.7,"t0":25.85,"t1":27.135},{"id":"n04","text":"And now you do.","at":54.87,"t0":27.435,"t1":28.44},{"id":"o02","text":"He says you two were at a chai stall. So what did you drink?","at":57.58,"t0":28.79,"t1":32.385},{"id":"o03","text":"How much did you pay?","at":67.17,"t0":33.585,"t1":35.255},{"id":"o04","text":"Same as his statement.","at":72.71,"t0":36.355,"t1":38.385},{"id":"n06","text":"Everything you know about that night, he told you.","at":78.17,"t0":39.085,"t1":41.485},{"id":"n06b","text":"So where was he, really?","at":84.37,"t0":42.185,"t1":43.415},{"id":"n07","text":"He was here.","at":88.63,"t0":44.315,"t1":45.14},{"id":"o05","text":"Alibi confirmed. He can go.","at":93.28,"t0":46.64,"t1":49.19},{"id":"n08","text":"You just set a robber free.","at":99.38,"t0":49.69,"t1":51.065},{"id":"f02","text":"Next time, I'll pay.","at":104.13,"t0":52.065,"t1":53.4},{"id":"o06","text":"One more thing. The chaiwala. Old or young?","at":108,"t0":54,"t1":57.315},{"id":"n12","text":"You never saw him.","at":117.43,"t0":58.715,"t1":59.87},{"id":"n13","text":"One question put him there.","at":120.54,"t0":60.27,"t1":61.72},{"id":"n14","text":"Now do this to a friend.","at":124.84,"t0":62.42,"t1":63.79}];
